package com.ecommerce.user_service.controller;
import com.ecommerce.user_service.service.FavoriteService;import jakarta.validation.Valid;import jakarta.validation.constraints.Positive;import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users/me/favorites")public class FavoriteController{private final FavoriteService service;public FavoriteController(FavoriteService s){service=s;}@GetMapping public Map<String,Object> list(@AuthenticationPrincipal Jwt jwt){return service.list(uid(jwt));}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Map<String,Object> add(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody FavoriteRequest r){return service.add(uid(jwt),r.restaurantId());}@DeleteMapping("/{restaurantId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void remove(@AuthenticationPrincipal Jwt jwt,@PathVariable @Positive long restaurantId){service.remove(uid(jwt),restaurantId);}private long uid(Jwt jwt){return Long.parseLong(jwt.getClaim("userId").toString());}public record FavoriteRequest(@Positive long restaurantId){}}
